#![feature(rustc_attrs)]
use vstd::*;

verus! {
    /// Given a non-empty slice `a` of i32 and a positive prefix length `n` (with `n <= a.len()`),
    /// returns an index `r` in `[0, n)` such that `a[r]` is a maximum over the prefix `a[0..n]`.
    pub fn findMax(a: &[i32], n: usize) -> (r: usize)
        requires
            // The array is non-empty, and the prefix length is positive and does not exceed the array length.
            a.len() > 0,
            n > 0,
            n <= a.len(),
        ensures
            // The returned index is within the prefix.
            r < n,
        ensures
            // For every position j in [0, n), a[r] >= a[j].
            forall(|j: usize| j < n ==> a[r] >= a[j]),
    {
        // We search linearly through the first n elements, tracking the index of the current maximum.
        let mut max_idx: usize = 0;
        let mut i: usize = 1;

        // Loop invariant:
        //  1) 1 <= i <= n
        //  2) 0 <= max_idx < i
        //  3) for all j < i, a[max_idx] >= a[j]
        // Decreases clause ensures termination.
        while i < n
            invariant
                i <= n,
                max_idx < i,
                forall(|j: usize| j < i ==> a[max_idx] >= a[j]),
            decreases n - i
        {
            if a[i] > a[max_idx] {
                max_idx = i;
            }
            i += 1;
        }

        // At this point, i == n, so:
        //   max_idx < n
        //   for all j < n, a[max_idx] >= a[j]
        max_idx
    }
}